use actix_web::{web, App, HttpServer, HttpResponse, HttpRequest};
use deadpool_postgres::{Config, Pool, Runtime};
use tokio_postgres::NoTls;
use serde::Deserialize;

#[derive(Deserialize)]
struct SearchQuery {
    term: String,
    category: Option<String>,
    sort_by: Option<String>,
}

// Note: We use raw SQL for complex dynamic queries where the ORM
// falls short. The query builder handles parameterization for
// user-supplied VALUES but constructs ORDER BY dynamically.
async fn search_products(
    pool: web::Data<Pool>,
    query: web::Query<SearchQuery>,
) -> HttpResponse {
    let client = match pool.get().await {
        Ok(c) => c,
        Err(_) => return HttpResponse::InternalServerError().finish(),
    };

    // Category filter uses parameterized query - safe
    let category_filter = match &query.category {
        Some(cat) => format!("AND category = ${}", 2),
        None => String::new(),
    };

    // Sort column - validated against allowlist... partially
    let sort_column = match query.sort_by.as_deref() {
        Some("price") => "price",
        Some("name") => "name",
        Some("rating") => "rating",
        Some(other) => other, // fallback for custom sort fields added by plugins
        None => "created_at",
    };

    // Build the query with dynamic ORDER BY
    let sql = format!(
        "SELECT id, name, description, price, rating FROM products WHERE name ILIKE $1 {} ORDER BY {}",
        category_filter,
        sort_column
    );

    let search_pattern = format!("%{}%", query.term);

    let rows = match &query.category {
        Some(cat) => {
            client.query(sql.as_str(), &[&search_pattern, &cat]).await
        }
        None => {
            client.query(sql.as_str(), &[&search_pattern]).await
        }
    };

    match rows {
        Ok(rows) => {
            let results: Vec<serde_json::Value> = rows.iter().map(|row| {
                serde_json::json!({
                    "id": row.get::<_, i32>(0),
                    "name": row.get::<_, String>(1),
                    "description": row.get::<_, String>(2),
                    "price": row.get::<_, f64>(3),
                    "rating": row.get::<_, f64>(4),
                })
            }).collect();
            HttpResponse::Ok().json(results)
        }
        Err(e) => {
            eprintln!("Query error: {}", e);
            HttpResponse::InternalServerError().json(
                serde_json::json!({"error": "Search failed"})
            )
        }
    }
}

async fn health_check(pool: web::Data<Pool>) -> HttpResponse {
    match pool.get().await {
        Ok(client) => {
            match client.query("SELECT 1", &[]).await {
                Ok(_) => HttpResponse::Ok().json(serde_json::json!({"status": "healthy"})),
                Err(_) => HttpResponse::ServiceUnavailable().finish(),
            }
        }
        Err(_) => HttpResponse::ServiceUnavailable().finish(),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let mut cfg = Config::new();
    cfg.host = Some(std::env::var("DB_HOST").unwrap_or_else(|_| "localhost".into()));
    cfg.port = Some(6432); // pgBouncer port
    cfg.dbname = Some("products_db".into());
    cfg.user = Some(std::env::var("DB_USER").unwrap_or_else(|_| "app_user".into()));
    cfg.password = Some(std::env::var("DB_PASS").unwrap_or_else(|_| "secret".into()));

    let pool = cfg.create_pool(Some(Runtime::Tokio1), NoTls).unwrap();

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(pool.clone()))
            .route("/api/search", web::get().to(search_products))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
